-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 4 : leçons 13 à 16.
-- Questions sur le texte (13.3, 14.3, 15.3, 16.3), synonymes (13.4, 14.4, 15.4 « -iri »), noms sans -ant- (15.4),
-- adjectifs et mots à trouver (15.4, 16.4).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Unuflanke granda idealismo kaj profunda kredo je la bono de la homa koro; aliflanke fera, malvarma racio kaj neŝanceligebla logiko.' WHERE id = 1440 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar lia granda morala supereco permesis al li superregi kaj harmoniigi ilin.' WHERE id = 1441 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: li neniam sekvis sian instinkton aŭ emocion, sed obeis nur al sia logika inteligenteco; ĉiu lia ago kaj vorto estis atente pesitaj.' WHERE id = 1442 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La lingvoj kaj la religioj. Li ellaboris du planojn, kiuj, respektante la lingvojn kaj religiojn, ebligu al la homoj renkontiĝi kaj toleri sin reciproke sur neŭtrala tereno: Esperanton kaj la homaranismon (hilelismon).' WHERE id = 1443 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: Esperanto rapide disvastiĝis tra la tuta terglobo, sed la homaranismo ne sukcesis kolekti adeptojn.' WHERE id = 1444 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: lingvo estas praktika ilo, kiun ĉiu povas uzi sendepende de siaj konvinkoj, dum religia aŭ filozofia doktrino tuŝas la internan vivon kaj la kredojn de la homoj.' WHERE id = 1445 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar li volis pacience elprovi plurajn formojn de la lingvo: dum naŭ jaroj li korektis kaj refaris ilin ĝis la definitiva.' WHERE id = 1446 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝi neniam tuŝetis lian saĝecon: li klopodis senpersonigi la lingvon, forĵetis ĉiajn rajtojn kaj rifuzis esti leĝofaranto de la lingvo kaj gvidanto de la Movado.' WHERE id = 1447 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Lingva Komitato (nuntempe la Akademio), kies decidoj estu devigaj por ĉiuj.' WHERE id = 1448 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar reformoj dependas de la preferoj de unuopaj personoj: oni neniam povus kontentigi ĉies postulojn kaj devus senĉese aldoni reformojn al reformoj.' WHERE id = 1449 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La reciproka malkonfido de la tiutempaj francaj gvidantoj: lia projekto eĉ ne estis diskutata en la Kongreso de 1905.' WHERE id = 1450 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiel malplimulta avangardo, ili devas maturigi la cirkonstancojn, en kiuj la Internacia Lingvo atingos sian finan celon. Per sia persona propagando ili estas prototipoj, laŭ kiuj la publiko juĝas la ideon de komuna lingvo.' WHERE id = 1451 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Socia eliteco: la aktivaj movadanoj estu homoj serioze respektataj en sia ĉiutaga vivo. Kultura eliteco: la Movado havu altan kulturan nivelon por gajni la simpation de la intelektularo. Eliteco de metodoj: distingi la celon de la rimedoj kaj simboloj, kaj informi per konkretaj faktoj kaj avantaĝoj prefere ol per sentimentalaj argumentoj.' WHERE id = 1452 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Senĉese ampleksigi sian propran klerecon: ĉiutage plivastigi sian kulturon.' WHERE id = 1453 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malgraŭ sia peza vivo, li ne pasigis eĉ unu tagon sen intelekta laboro: nokte li tradukis, verkis paroladojn kaj leterojn, ellaboris la hilelismon, verkis gramatikon de la jida, kaj li konis 12 lingvojn.' WHERE id = 1454 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ili estas nepre havindaj, sed nur provizoraj rimedoj por la fina celo: la enkonduko de Esperanto en ĉiujn internaciajn rilatojn. Oni taksu la progreson ne interne de la societoj, sed ĉe la publika opinio.' WHERE id = 1455 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Neniu el ambaŭ: la du vojoj estas nedisigeblaj; agnosko de supre kuraĝigas la disvastigon malsupre, kaj vasta uzado malsupre trenas oficialajn rekonojn de supre.' WHERE id = 1456 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne pliajn idealojn, sed praktikan solvon de la lingva ĥaoso: ekonomion de tempo, ekzaktecon kaj defendon de la naciaj lingvoj kontraŭ lingvaj diskriminacioj. Ĝi ankaŭ kontribuas al la disvastigo de scienco kaj kulturo.' WHERE id = 1457 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Laŭ li, la idealismo estas privata afero de ĉiu esperantisto: la Movado prezentu Esperanton kiel lingvon kaj praktikan solvon, per konkretaj faktoj, ne per sentimentalaj argumentoj. Eĉ Zamenhof oferis siajn flankajn idealojn al la bono de Esperanto.' WHERE id = 1458 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉiu persono, kiu scias kaj uzas la lingvon Esperanto, tute egale por kiaj celoj li ĝin uzas.' WHERE id = 1459 AND ekzerco_id = 173 AND COALESCE(respondo, '') = '';
