UPDATE ekzerceroj SET respondo = 'konjekti (aŭ: supozi)' WHERE id = 1486 AND ekzerco_id = 176 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'ŝanco (aŭ: sorto, akcidento)' WHERE id = 1487 AND ekzerco_id = 176 AND COALESCE(respondo, '') = '';
