UPDATE ekzerceroj SET respondo = 'faligi (aŭ: inversigi)' WHERE id = 1489 AND ekzerco_id = 176 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Nokte, sur malhela teraso super la maro, kie oni aŭdis la ondojn inter la rifoj.' WHERE id = 1491 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li diris, ke li devas mortigi sian avinjon, ĉar ŝi jam mortis.' WHERE id = 1492 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar avinjo Dalia tre deziris vojaĝi lastan fojon, kaj lia edzino Elna pledis por ŝi: la kompatinda avinjo neniam forlasis sian provincan urbeton.' WHERE id = 1493 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉe la Côte d’Azur, en Cannes.' WHERE id = 1494 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la transporto de kadavro kostus terure, postulus multajn formalaĵojn kaj malfruigus ilian revenon je tagoj aŭ semajnoj, kio damaĝus lian entreprenon.' WHERE id = 1495 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ili sidigis la mortintan avinjon en ombra angulo de la aŭto, kovritan per ŝaloj, kvazaŭ dormantan; ŝi “mortu” oficiale post la landlimo, kun helpo de la familia kuracisto. La limtransiro sukcesis: neniu rimarkis ion.' WHERE id = 1496 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Por vespermanĝi en restoracio, ili lasis la aŭton ŝlosita, kun la avinjo interne, en malluma strateto de urbo; kiam ili revenis, ĝi estis ŝtelita.' WHERE id = 1497 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar la polico pridemandus ilin pri la enhavo de la aŭto, kaj ili ne povis konfesi, ke ili transportis kadavron.' WHERE id = 1498 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Matene, ĉe kurbo de kampara vojeto ekster la urbo; ĉio estis netuŝita, sed la avinjo mankis.' WHERE id = 1499 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Preterpasanta kamparano; li forkuris, ĉar Elna respondis, ke ili perdis kadavron.' WHERE id = 1500 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ili venigis siajn gekuzojn kaj sincere klarigis al ili la situacion; poste ili vivis izolite, vidante neniun kaj parolante al neniu.' WHERE id = 1501 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: konfesi la veron al la aŭtoritatoj kaj akcepti la sekvojn, aŭ atendi, ĝis oni trovos la kadavron.' WHERE id = 1502 AND ekzerco_id = 178 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'ripari' WHERE id = 1523 AND ekzerco_id = 181 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'rezisti (aŭ: persisti)' WHERE id = 1524 AND ekzerco_id = 181 AND COALESCE(respondo, '') = '';
