UPDATE ekzerceroj SET respondo = 'apatia (aŭ: indiferenta, malvigla)' WHERE id = 1531 AND ekzerco_id = 181 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'frosta (aŭ: glacia)' WHERE id = 1532 AND ekzerco_id = 181 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La plej densa parto de nia galaksio, al kiu apartenas ankaŭ la Suno kun siaj planedoj.' WHERE id = 1535 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Same kiel la galaksio konsistas el steloj, la Universo konsistas el multego da galaksioj.' WHERE id = 1536 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La galaksio en la konstelacio de Andromedo.' WHERE id = 1537 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ne: ĝi estas pli ol du milionojn da lumjaroj malproksime, do ni vidas ĝin tia, kia ĝi estis antaŭ du milionoj da jaroj, kiam la homo ankoraŭ ne ekzistis.' WHERE id = 1538 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke la galaksioj fuĝas ĉiuflanken, for de la Lakta Vojo, kvazaŭ ĝi estus la centro de la Universo (en 1929).' WHERE id = 1539 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Jes. Ekzemple: la radiondoj kaptataj de radioteleskopoj, aliaj radiadoj (iksradioj, gamaradioj) aŭ kosmaj partikloj.' WHERE id = 1540 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ondolongo (aŭ frekvenco) de la lumo: pli da ondoj en sekundo donas bluan koloron, malpli donas ruĝan.' WHERE id = 1541 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiam la fonto de sono aŭ lumo alproksimiĝas al ni, ni ricevas pli da ondoj en sekundo (pli alta sono, lumo ŝovita al la bluo); kiam ĝi malproksimiĝas, ni ricevas malpli (pli malalta sono, lumo ŝovita al la ruĝo). Ekzemple, la fajfado de lokomotivo subite malaltiĝas, kiam ĝi pasas preter ni.' WHERE id = 1542 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke ĉiuj galaksioj malproksimiĝas de ni, kaj des pli rapide, ju pli malproksimaj ili estas: la Universo ŝajnas eksplodi.' WHERE id = 1543 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ke komence ekzistis nur unu granda praatomo, enhavanta la tutan materion kaj energion de la Kosmo; ĝi eksplodis, kaj tial la Universo ankoraŭ nun ekspansiiĝas.' WHERE id = 1544 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar oni iam trovus galaksion fuĝantan pli rapide ol la lumo, kio estas neebla laŭ la teorio de relativeco de Einstein.' WHERE id = 1545 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Se la kosmospaco mem plivastiĝas, la fuĝado de la galaksioj estus nur ŝajna (kiel ŝanĝo en la lenso de mikroskopo), kaj la Doppler-principo ne povas pruvi realan movon de la galaksioj.' WHERE id = 1546 AND ekzerco_id = 184 AND COALESCE(respondo, '') = '';
