UPDATE ekzerceroj SET respondo = 'Mirinda peonio, kies brileruĝaj floroj eligis ebriigan parfumon.' WHERE id = 1597 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi rompis florantan branĉon de la multvalora peonio kaj ne povis pagi la kompenson, kiun postulis la bonzoj. Tu Thuk liberigis ŝin, donante sian brokatan tunikon.' WHERE id = 1598 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li forvojaĝis kun knabo, kiu portis brandujon kaj gitaron, kaj vagadis en malmulte frekventitaj lokoj, trinkante, muzikante kaj verkante poemojn.' WHERE id = 1599 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La enirejo fermiĝis malantaŭ li kaj plena mallumo ĉirkaŭis lin; li daŭrigis blindpalpe laŭ longa kaj zigzaga vojo, ĝis li ekvidis lumeton.' WHERE id = 1600 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'En vastan ĝardenon de florantaj persikarboj; du blujakaj servantinoj, kiuj atendis lin, kondukis lin al la palaco.' WHERE id = 1601 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi estis majesta kaj bela, tute blanke vestita, kaj sidis sur trono el blanka santalligno.' WHERE id = 1602 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi donis al li sian filinon Ĉiela Parfumo kiel edzinon, por danki lin, ĉar li savis ŝin ĉe la pagodo.' WHERE id = 1603 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Unu jaron laŭ lia sento; sed sur la tero dume pasis proksimume unu jarcento.' WHERE id = 1604 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Blanka velo sur la maro vekis en li hejmsopiron: li volis revidi sian naskiĝlandon kaj siajn familianojn.' WHERE id = 1605 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar ŝi sciis, ke ili neniam plu revidos unu la alian. Tu Thuk ne sciis, ke unu jaro en la feinlando egalas al jarcento sur la tero: liaj familianoj delonge mortis, kaj li ne povos reveni.' WHERE id = 1606 AND ekzerco_id = 191 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'raŭka' WHERE id = 1635 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
