UPDATE ekzerceroj SET respondo = 'preciza (aŭ: strikta, rigora)' WHERE id = 1637 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'romantika (aŭ: sentimentala)' WHERE id = 1638 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'iritiĝema (aŭ: nervoza, kolerema)' WHERE id = 1639 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'frivola (aŭ: supraĵa)' WHERE id = 1640 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'vana' WHERE id = 1641 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'unika' WHERE id = 1642 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'ŝaŭma' WHERE id = 1643 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'abstrakta' WHERE id = 1644 AND ekzerco_id = 195 AND COALESCE(respondo, '') = '';

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (173, 176, 178, 181, 184, 186, 187, 188, 191, 195) AND forigita = 0 GROUP BY ekzerco_id;
